# SPSC リングバッファ（割り込みセーフ）

## `spsc_ring.h`

```c
#ifndef SPSC_RING_H
#define SPSC_RING_H

#include <stdint.h>
#include <stddef.h>
#include <stdatomic.h>

/*
 * Single-Producer / Single-Consumer Ring Buffer
 *
 * Design principles:
 *   - Producer may run in an ISR (or main context); consumer runs in main context.
 *   - No locks, no mutexes. Correctness relies on:
 *       * Only one writer per index variable.
 *       * Only one reader per index variable.
 *       * Memory barriers (via _Atomic acquire/release) guarantee ordering.
 *   - Capacity MUST be a power of 2 (enforced at init).
 *   - Indices overflow naturally (uint32_t wrap-around); difference
 *     `head - tail` always yields the correct number of pending items.
 */

typedef struct {
    _Atomic uint32_t head;   /* next write position (producer only)   */
    _Atomic uint32_t tail;   /* next read position  (consumer only)   */
    uint32_t capacity;       /* power-of-2 capacity                   */
    uint32_t mask;           /* capacity - 1                          */
    uint8_t *buf;            /* backing storage (capacity bytes)      */
} spsc_ring_t;

/* ---- API ---- */

/**
 * Initialize the ring buffer.
 * `capacity` must be a power of 2 and > 0.
 * `buf` must point to at least `capacity` bytes of storage.
 * Returns 0 on success, -1 on invalid arguments.
 */
int spsc_ring_init(spsc_ring_t *ring, uint8_t *buf, uint32_t capacity);

/**
 * Producer: push one byte into the ring.
 * Safe to call from an ISR.
 * Returns 1 on success, 0 if the ring is full (data dropped).
 */
int spsc_ring_push(spsc_ring_t *ring, uint8_t byte);

/**
 * Producer: push multiple bytes.
 * Returns the number of bytes actually written (0 if full).
 */
uint32_t spsc_ring_push_bulk(spsc_ring_t *ring, const uint8_t *data, uint32_t len);

/**
 * Consumer: pop one byte from the ring.
 * Returns 1 on success, 0 if the ring is empty.
 */
int spsc_ring_pop(spsc_ring_t *ring, uint8_t *byte);

/**
 * Consumer: pop up to `max_len` bytes.
 * Returns the number of bytes actually read.
 */
uint32_t spsc_ring_pop_bulk(spsc_ring_t *ring, uint8_t *out, uint32_t max_len);

/** Query helpers (non-destructive). */
uint32_t spsc_ring_count(const spsc_ring_t *ring);  /* items available  */
uint32_t spsc_ring_free(const spsc_ring_t *ring);   /* free slots       */
int      spsc_ring_is_empty(const spsc_ring_t *ring);
int      spsc_ring_is_full(const spsc_ring_t *ring);

#endif /* SPSC_RING_H */
```

## `spsc_ring.c`

```c
#include "spsc_ring.h"
#include <string.h>

/* ---------- helpers ---------- */

static int is_power_of_2(uint32_t v)
{
    return v != 0 && (v & (v - 1)) == 0;
}

/* ---------- init ---------- */

int spsc_ring_init(spsc_ring_t *ring, uint8_t *buf, uint32_t capacity)
{
    if (!ring || !buf || !is_power_of_2(capacity))
        return -1;

    atomic_store_explicit(&ring->head, 0,    memory_order_relaxed);
    atomic_store_explicit(&ring->tail, 0,    memory_order_relaxed);
    ring->capacity = capacity;
    ring->mask     = capacity - 1;
    ring->buf      = buf;
    return 0;
}

/* ---------- producer ---------- */

int spsc_ring_push(spsc_ring_t *ring, uint8_t byte)
{
    /* Read tail with acquire: ensures we see the consumer's latest progress. */
    uint32_t tail = atomic_load_explicit(&ring->tail, memory_order_acquire);
    uint32_t head = ring->head;  /* producer is the only writer → relaxed load */

    if (head - tail >= ring->capacity)
        return 0;  /* full — drop */

    ring->buf[head & ring->mask] = byte;

    /* Release: guarantees the byte write is visible before head advances. */
    atomic_store_explicit(&ring->head, head + 1, memory_order_release);
    return 1;
}

uint32_t spsc_ring_push_bulk(spsc_ring_t *ring, const uint8_t *data, uint32_t len)
{
    uint32_t tail = atomic_load_explicit(&ring->tail, memory_order_acquire);
    uint32_t head = ring->head;
    uint32_t space = ring->capacity - (head - tail);

    if (len > space)
        len = space;
    if (len == 0)
        return 0;

    /* Two segments: [head .. capacity) and [0 .. head) wrapped */
    uint32_t first = ring->capacity - (head & ring->mask);
    if (len <= first) {
        memcpy(&ring->buf[head & ring->mask], data, len);
    } else {
        memcpy(&ring->buf[head & ring->mask], data, first);
        memcpy(&ring->buf[0], data + first, len - first);
    }

    atomic_store_explicit(&ring->head, head + len, memory_order_release);
    return len;
}

/* ---------- consumer ---------- */

int spsc_ring_pop(spsc_ring_t *ring, uint8_t *byte)
{
    /* Read head with acquire: ensures we see the producer's latest data. */
    uint32_t head = atomic_load_explicit(&ring->head, memory_order_acquire);
    uint32_t tail = ring->tail;  /* consumer is the only writer → relaxed load */

    if (head == tail)
        return 0;  /* empty */

    *byte = ring->buf[tail & ring->mask];

    /* Release: guarantees the byte read completes before tail advances
       (prevents the producer from overwriting too early). */
    atomic_store_explicit(&ring->tail, tail + 1, memory_order_release);
    return 1;
}

uint32_t spsc_ring_pop_bulk(spsc_ring_t *ring, uint8_t *out, uint32_t max_len)
{
    uint32_t head = atomic_load_explicit(&ring->head, memory_order_acquire);
    uint32_t tail = ring->tail;
    uint32_t avail = head - tail;

    if (max_len > avail)
        max_len = avail;
    if (max_len == 0)
        return 0;

    uint32_t first = ring->capacity - (tail & ring->mask);
    if (max_len <= first) {
        memcpy(out, &ring->buf[tail & ring->mask], max_len);
    } else {
        memcpy(out, &ring->buf[tail & ring->mask], first);
        memcpy(out + first, &ring->buf[0], max_len - first);
    }

    atomic_store_explicit(&ring->tail, tail + max_len, memory_order_release);
    return max_len;
}

/* ---------- queries ---------- */

uint32_t spsc_ring_count(const spsc_ring_t *ring)
{
    uint32_t head = atomic_load_explicit(
        (volatile _Atomic uint32_t *)&ring->head, memory_order_acquire);
    uint32_t tail = atomic_load_explicit(
        (volatile _Atomic uint32_t *)&ring->tail, memory_order_acquire);
    return head - tail;
}

uint32_t spsc_ring_free(const spsc_ring_t *ring)
{
    return ring->capacity - spsc_ring_count(ring);
}

int spsc_ring_is_empty(const spsc_ring_t *ring)
{
    return spsc_ring_count(ring) == 0;
}

int spsc_ring_is_full(const spsc_ring_t *ring)
{
    return spsc_ring_count(ring) == ring->capacity;
}
```

## `example.c`

```c
#include <stdio.h>
#include <string.h>
#include "spsc_ring.h"

/*
 * Simulated ISR handler — in a real MCU this would be registered as
 * an interrupt handler (e.g., UART RX ISR).
 */
static spsc_ring_t g_ring;
static uint8_t     g_buf[1024];  /* 1 KiB ring */

/* Simulated interrupt: called from ISR context */
void uart_rx_isr(void)
{
    uint8_t byte = 0x42;  /* pretend we received 'B' */
    spsc_ring_push(&g_ring, byte);
}

int main(void)
{
    if (spsc_ring_init(&g_ring, g_buf, 1024) != 0) {
        fprintf(stderr, "init failed\n");
        return 1;
    }

    /* Simulate 10 ISR invocations */
    for (int i = 0; i < 10; i++) {
        uart_rx_isr();
    }

    printf("Ring count after 10 pushes: %u\n", spsc_ring_count(&g_ring));

    /* Consumer: drain the ring */
    uint8_t received[10];
    uint32_t n = spsc_ring_pop_bulk(&g_ring, received, 10);
    printf("Popped %u bytes:", n);
    for (uint32_t i = 0; i < n; i++)
        printf(" 0x%02X", received[i]);
    printf("\n");

    /* Single-byte pop loop */
    uint8_t b;
    while (spsc_ring_pop(&g_ring, &b))
        printf("popped 0x%02X\n", b);

    printf("Ring empty: %s\n", spsc_ring_is_empty(&g_ring) ? "yes" : "no");

    return 0;
}
```

