## `ringbuf.c`

```c
#include "ringbuf.h"
#include <string.h>

/* size が 2の冪乗かチェック (呼び出し時に assert 推奨) */
static inline int is_pow2(size_t n) { return n != 0 && (n & (n - 1)) == 0; }

void ringbuf_init(ringbuf_t *rb, uint8_t *storage, size_t size)
{
    /* 開発時: assert(is_pow2(size)); */
    rb->head  = 0;
    rb->tail  = 0;
    rb->size  = size;
    rb->mask  = size - 1;
    rb->buf   = storage;
}

/* ---- ブロック版: 円形コピー ---- */
size_t ringbuf_put_block(ringbuf_t *rb, const uint8_t *src, size_t n)
{
    size_t h = rb->head;
    size_t t = rb->tail;
    size_t free = rb->size - (h - t);

    if (n > free) n = free;
    if (n == 0) return 0;

    size_t idx = h & rb->mask;
    /* 円形なので 2 分割の可能性あり */
    size_t first = rb->size - idx;   /* 末尾までの残り */
    if (first >= n) {
        memcpy(rb->buf + idx, src, n);
    } else {
        memcpy(rb->buf + idx, src, first);
        memcpy(rb->buf, src + first, n - first);
    }

    RINGBUF_BARRIER();
    rb->head = h + n;
    return n;
}

size_t ringbuf_get_block(ringbuf_t *rb, uint8_t *dst, size_t n)
{
    size_t t = rb->tail;
    size_t h = rb->head;
    size_t avail = h - t;

    if (n > avail) n = avail;
    if (n == 0) return 0;

    size_t idx = t & rb->mask;
    size_t first = rb->size - idx;
    if (first >= n) {
        memcpy(dst, rb->buf + idx, n);
    } else {
        memcpy(dst, rb->buf + idx, first);
        memcpy(dst + first, rb->buf, n - first);
    }

    RINGBUF_BARRIER();
    rb->tail = t + n;
    return n;
}
```

