## `example.c` — ISR + 通常タスクの使用例

```c
#include <stdio.h>
#include <string.h>
#include "ringbuf.h"

/* ---- 共有バッファ (静的確保) ---- */
#define BUF_SIZE 256u   /* 2の冪乗 */
static uint8_t  storage[BUF_SIZE];
static ringbuf_t rb;

/* ---- "ISR" 側: UART RX 割り込みを模倣 ---- */
/* 実際の MCU では ISR 内で ringbuf_put() を呼ぶだけ */
static void uart_rx_isr(void)
{
    /* 例: 1バイト受信したと仮定 */
    uint8_t dummy = 0x42;
    ringbuf_put(&rb, dummy);   /* 満杯なら無視 (ISR 内なので printf 不可) */
}

/* ---- 通常タスク (コンシューマ) ---- */
static void consumer_task(void)
{
    uint8_t buf[64];
    size_t n = ringbuf_get_block(&rb, buf, sizeof(buf));
    if (n > 0) {
        printf("consumed %zu bytes: ", n);
        for (size_t i = 0; i < n; i++) printf("%02X ", buf[i]);
        printf("\n");
    }
}

int main(void)
{
    ringbuf_init(&rb, storage, BUF_SIZE);

    /* ISR を複数回呼んだ想定 */
    for (int i = 0; i < 32; i++) uart_rx_isr();

    printf("buffer count = %zu\n", ringbuf_count(&rb));

    consumer_task();

    printf("after consume, count = %zu\n", ringbuf_count(&rb));
    return 0;
}
```

