## 1. `ring_buffer.h`

```c
#ifndef RING_BUFFER_H
#define RING_BUFFER_H

#include <stdatomic.h>
#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>

typedef struct ring_buffer {
    void *buffer;
    size_t capacity;
    size_t elem_size;
    size_t mask;

    /*
     * head: 次に書き込むスロット番号の index
     * tail: 次に読み出すスロット番号の index
     *
     * head と tail は単調増加させる。
     * 実際のスロット番号は index & mask で求める。
     */
    _Atomic size_t head;
    _Atomic size_t tail;
} ring_buffer_t;

bool rb_init(ring_buffer_t *rb,
             void *buffer,
             size_t capacity,
             size_t elem_size);

bool rb_is_empty(ring_buffer_t *rb);
bool rb_is_full(ring_buffer_t *rb);

bool rb_push(ring_buffer_t *rb, const void *item);
bool rb_pop(ring_buffer_t *rb, void *item);

void rb_reset(ring_buffer_t *rb);

#endif /* RING_BUFFER_H */
```

