## 2. `ring_buffer.c`

```c
#include "ring_buffer.h"

#include <string.h>

static inline bool is_power_of_two(size_t n)
{
    return n != 0 && (n & (n - 1)) == 0;
}

bool rb_init(ring_buffer_t *rb,
             void *buffer,
             size_t capacity,
             size_t elem_size)
{
    if (rb == NULL || buffer == NULL) {
        return false;
    }

    if (capacity == 0 || elem_size == 0) {
        return false;
    }

    if (!is_power_of_two(capacity)) {
        return false;
    }

    rb->buffer = buffer;
    rb->capacity = capacity;
    rb->elem_size = elem_size;
    rb->mask = capacity - 1;

    atomic_store_explicit(&rb->head, 0, memory_order_relaxed);
    atomic_store_explicit(&rb->tail, 0, memory_order_relaxed);

    return true;
}

/*
 * 現在の要素数。
 * size_t は unsigned なので、差がオーバーフローしても定義された wrap-around になる。
 */
static inline size_t rb_count(ring_buffer_t *rb)
{
    size_t h = atomic_load_explicit(&rb->head, memory_order_acquire);
    size_t t = atomic_load_explicit(&rb->tail, memory_order_acquire);

    return h - t;
}

bool rb_is_empty(ring_buffer_t *rb)
{
    return rb_count(rb) == 0;
}

bool rb_is_full(ring_buffer_t *rb)
{
    return rb_count(rb) >= rb->capacity;
}

/*
 * プロデューサ用。
 * 1 つのプロデューサコンテキストだけから呼ぶこと。
 * 例: ISR だけ、またはタスクだけ。
 */
bool rb_push(ring_buffer_t *rb, const void *item)
{
    if (rb == NULL || item == NULL) {
        return false;
    }

    /*
     * head はプロデューサだけが更新するので relaxed で読める。
     * tail はコンシューマが更新するため acquire で読む。
     */
    size_t h = atomic_load_explicit(&rb->head, memory_order_relaxed);
    size_t t = atomic_load_explicit(&rb->tail, memory_order_acquire);

    if (h - t >= rb->capacity) {
        return false;
    }

    size_t slot = h & rb->mask;
    memcpy((char *)rb->buffer + slot * rb->elem_size, item, rb->elem_size);

    /*
     * データ書き込みを完了してから head を進める。
     * release store により、コンシューマが head を acquire load した時点で
     * データ書き込みが可視化される。
     */
    atomic_store_explicit(&rb->head, h + 1, memory_order_release);

    return true;
}

/*
 * コンシューマ用。
 * 1 つのコンシューマコンテキストだけから呼ぶこと。
 */
bool rb_pop(ring_buffer_t *rb, void *item)
{
    if (rb == NULL || item == NULL) {
        return false;
    }

    /*
     * tail はコンシューマだけが更新するので relaxed で読める。
     * head はプロデューサが更新するため acquire で読む。
     */
    size_t t = atomic_load_explicit(&rb->tail, memory_order_relaxed);
    size_t h = atomic_load_explicit(&rb->head, memory_order_acquire);

    if (h == t) {
        return false;
    }

    size_t slot = t & rb->mask;
    memcpy(item, (char *)rb->buffer + slot * rb->elem_size, rb->elem_size);

    /*
     * データコピーを完了してから tail を進める。
     */
    atomic_store_explicit(&rb->tail, t + 1, memory_order_release);

    return true;
}

void rb_reset(ring_buffer_t *rb)
{
    if (rb == NULL) {
        return;
    }

    atomic_store_explicit(&rb->head, 0, memory_order_relaxed);
    atomic_store_explicit(&rb->tail, 0, memory_order_relaxed);
}
```

