## 3. 使用例

### `example.c`

```c
#include "ring_buffer.h"

#include <stdio.h>
#include <stdint.h>

#define RING_CAPACITY 16

typedef struct message {
    uint32_t id;
    uint32_t value;
} message_t;

static ring_buffer_t rb;
static message_t ring_storage[RING_CAPACITY];

/*
 * 例: ISR から push する想定。
 * 実際のハードウェアでは ISR 属性やハンドラ登録が必要。
 */
void producer_isr(void)
{
    static uint32_t id = 0;

    message_t msg = {
        .id = id++,
        .value = id * 10,
    };

    if (!rb_push(&rb, &msg)) {
        /*
         * フルなら捨てる、カウントする、別の処理をする。
         * ISR 内なので printf は通常使わない。
         */
    }
}

int main(void)
{
    if (!rb_init(&rb, ring_storage, RING_CAPACITY, sizeof(message_t))) {
        fprintf(stderr, "ring buffer init failed\n");
        return 1;
    }

    /*
     * 例として ISR 相当の producer を呼ぶ。
     */
    for (int i = 0; i < 20; i++) {
        producer_isr();
    }

    /*
     * コンシューマ側。
     */
    while (!rb_is_empty(&rb)) {
        message_t msg;

        if (rb_pop(&rb, &msg)) {
            printf("id=%u value=%u\n", msg.id, msg.value);
        }
    }

    return 0;
}
```

