## 6. 最短の byte 版例

もし `uint8_t` だけの ring buffer でよければ、もっと単純にできます。

```c
#include <stdatomic.h>
#include <stdbool.h>

#define RB_CAPACITY 32

static uint8_t rb_buf[RB_CAPACITY];
static _Atomic size_t rb_head;
static _Atomic size_t rb_tail;

bool rb_push_byte(uint8_t b)
{
    size_t h = atomic_load_explicit(&rb_head, memory_order_relaxed);
    size_t t = atomic_load_explicit(&rb_tail, memory_order_acquire);

    if (h - t >= RB_CAPACITY) {
        return false;
    }

    rb_buf[h & (RB_CAPACITY - 1)] = b;
    atomic_store_explicit(&rb_head, h + 1, memory_order_release);

    return true;
}

bool rb_pop_byte(uint8_t *out)
{
    size_t t = atomic_load_explicit(&rb_tail, memory_order_relaxed);
    size_t h = atomic_load_explicit(&rb_head, memory_order_acquire);

    if (h == t) {
        return false;
    }

    *out = rb_buf[t & (RB_CAPACITY - 1)];
    atomic_store_explicit(&rb_tail, t + 1, memory_order_release);

    return true;
}
```

